1: // ---------------------------------------------------------------------------
2: // Ignore policy — hardcoded common dependency/build directories
3: // ---------------------------------------------------------------------------
4: 
5: const BASELINE_IGNORED_NAMES = [
6:   // Version control
7:   '.git', '.claude',
8:   // JavaScript / Node
9:   'node_modules', '.node_modules', '.npm-cache', '.npm', '.pnpm-store', '.yarn',
10:   // Python
11:   '__pycache__', '.venv', 'venv', '.env', '.tox', '.pytest_cache', '.mypy_cache',
12:   // Ruby
13:   '.bundle', 'vendor',
14:   // Java / Kotlin / Scala
15:   'target',
16:   // Rust
17:   // (also 'target', already included above)
18:   // Go
19:   'pkg',
20:   // Build outputs
21:   'dist', 'build', 'out', 'coverage', '.cache',
22:   // Misc tooling
23:   'bower_components', '.parcel-cache', '.next', '.nuxt', '.svelte-kit',
24:   // Gradle
25:   '.gradle', '.gradle-user-home-local', '.gradle-user-home', '.gradle-native', '.gradle-native-test',
26:   // Project-specific
27:   'thinking_bench',
28: ];
29: 
30: // Root-relative path prefixes (forward-slash separated, no leading slash).
31: const BASELINE_IGNORED_PATHS = [
32:   'eval/results',
33:   'eval/fixtures',
34:   'tmp-find',
35: ];
36: 
37: export type IgnorePolicy = {
38:   names: string[];
39:   namesLower: Set<string>;
40:   paths: string[];
41: };
42: 
43: export function buildIgnorePolicy(_repoRoot: string): IgnorePolicy {
44:   const names: string[] = [];
45:   const seen = new Set<string>();
46: 
47:   for (const name of BASELINE_IGNORED_NAMES) {
48:     const key = name.toLowerCase();
49:     if (seen.has(key)) continue;
50:     seen.add(key);
51:     names.push(name);
52:   }
53: 
54:   return {
55:     names,
56:     namesLower: new Set(names.map((n) => n.toLowerCase())),
57:     paths: [...BASELINE_IGNORED_PATHS],
58:   };
59: }
