18:   assert.equal(evaluateCommandSafety('git status --short | Where-Object { $_ -match "src" }').safe, true);
19: });
20: 
21: test('evaluateCommandSafety rejects every producer other than git', () => {
22:   // Every other repo tool executes natively from typed args, so no other command
23:   // token may reach a shell.
24:   for (const command of [
25:     'rg -n "planner" src',
26:     'Get-Content src\\summary.ts',
27:     'Select-String -Path "src\\*.ts" -Pattern "planner"',
28:     'Get-ChildItem src -Recurse',
29:     'pwd',
30:     'ls src',
31:   ]) {
32:     const result = evaluateCommandSafety(command);
