34:     assert.match(result.reason || '', /is not in the allow-list/u);
35:   }
36: });
37: 
38: test('evaluateCommandSafety rejects an empty command', () => {
39:   assert.equal(evaluateCommandSafety('   ').safe, false);
40:   assert.equal(evaluateCommandSafety('   ').reason, 'empty command');
41: });
42: 
43: test('evaluateCommandSafety rejects a non-read-only pipe stage', () => {
44:   const result = evaluateCommandSafety('git log --oneline | findstr summary');
45:   assert.equal(result.safe, false);
46:   assert.match(result.reason || '', /is not in the allow-list/u);
47: });
48: 
49: test('evaluateCommandSafety rejects a ForEach-Object stage that writes', () => {
50:   const result = evaluateCommandSafety('git log --oneline | ForEach-Object { Rename-Item $_ }');
51:   assert.equal(result.safe, false);
52:   assert.equal(result.reason, 'ForEach-Object must be read-only');
53: });
54: 
