73:   assert.equal(evaluateCommandSafety('git -C D:\\personal\\models log', repoRoot).safe, false);
74:   assert.equal(
75:     evaluateCommandSafety('git -C C:\\Users\\denys\\Documents\\GitHub\\SiftKit\\src log', repoRoot).safe,
76:     true,
77:   );
78: });
