62: // Command safety evaluation
63: //
64: // Every repo tool except `git` executes natively from typed args (see
65: // engine/repo-tools.ts), so `git` is the only command string that ever reaches a
66: // shell. This gate is what stands between that string and PowerShell.
67: // ---------------------------------------------------------------------------
68: 
69: export type SafetyResult = {
70:   safe: boolean;
71:   reason: string | null;
72: };
73: 
74: const PRODUCER_COMMAND = 'git';
75: 
76: const READ_ONLY_PIPE_COMMANDS = new Set([
77:   'select-object', 'select-string', 'where-object', 'sort-object',
78:   'group-object', 'measure-object', 'foreach-object', 'format-table',
79:   'format-list', 'out-string', 'convertto-json', 'convertfrom-json',
80:   'get-unique', 'join-string',
81: ]);
82: 
83: const WRITE_OR_NETWORK_COMMAND_PATTERN = /\b(rm|del|mv|cp|move-item|copy-item|remove-item|set-content|add-content|out-file|export-[a-z0-9_-]+|tee-object|curl|wget|invoke-webrequest|invoke-restmethod|start-process)\b/iu;
84: 
85: const FOREACH_WRITE_COMMAND_PATTERN = /\b(set-content|add-content|out-file|export-[a-z0-9_-]+|tee-object|remove-item|move-item|copy-item|rename-item|invoke-webrequest|invoke-restmethod|start-process)\b/iu;
86: 
87: function hasBlockedOperator(command: string): boolean {
88:   let inSingle = false;
89:   let inDouble = false;
90: 
91:   for (let i = 0; i < command.length; i += 1) {
92:     const ch = command[i];
93:     if (ch === '`') {
94:       return true;
95:     }
96:     if (ch === "'" && !inDouble) {
97:       inSingle = !inSingle;
98:       continue;
99:     }
100:     if (ch === '"' && !inSingle) {
101:       inDouble = !inDouble;
102:       continue;
103:     }
104:     if (inSingle || inDouble) {
105:       continue;
106:     }
107:     if (ch === ';' || (ch === '&' && command[i + 1] === '&') || (ch === '|' && command[i + 1] === '|')) {
108:       return true;
109:     }
110:   }
111: 
112:   return false;
113: }
114: 
115: function hasFileRedirection(command: string): boolean {
116:   // Strip safe stderr-to-stdout merges (2>&1) before checking for real file redirects
117:   const withoutStderrMerge = command.replace(/\s*2>&1\s*/gu, ' ');
118:   return /[<>]/u.test(withoutStderrMerge);
119: }
120: 
121: function splitTopLevelPipes(command: string): string[] {
122:   const parts: string[] = [];
123:   let current = '';
124:   let inSingle = false;
125:   let inDouble = false;
126: 
127:   for (let i = 0; i < command.length; i += 1) {
128:     const ch = command[i];
129:     if (ch === "'" && !inDouble) {
130:       inSingle = !inSingle;
131:       current += ch;
132:       continue;
133:     }
134:     if (ch === '"' && !inSingle) {
135:       inDouble = !inDouble;
136:       current += ch;
137:       continue;
138:     }
139:     if (ch === '|' && !inSingle && !inDouble) {
140:       parts.push(current.trim());
141:       current = '';
142:       continue;
143:     }
144:     current += ch;
145:   }
146: 
147:   if (current.trim()) {
148:     parts.push(current.trim());
149:   }
150: 
151:   return parts;
152: }
153: 
154: export function getFirstCommandToken(segment: string): string {
155:   const match = /^\s*(\S+)/u.exec(segment);
156:   return match ? match[1].toLowerCase() : '';
157: }
158: 
159: function tokenizeSegment(segment: string): string[] {
160:   const tokens: string[] = [];
161:   let current = '';
162:   let inSingle = false;
163:   let inDouble = false;
164: 
165:   for (let i = 0; i < segment.length; i += 1) {
166:     const ch = segment[i];
167:     if (ch === "'" && !inDouble) {
168:       inSingle = !inSingle;
169:       continue;
170:     }
171:     if (ch === '"' && !inSingle) {
172:       inDouble = !inDouble;
173:       continue;
174:     }
175:     if (/\s/u.test(ch) && !inSingle && !inDouble) {
176:       if (current) {
177:         tokens.push(current);
178:         current = '';
179:       }
180:       continue;
181:     }
182:     current += ch;
183:   }
184: 
185:   if (current) {
186:     tokens.push(current);
187:   }
188: 
189:   return tokens;
190: }
191: 
192: function referencesPathOutsideRepo(command: string, repoRoot: string): boolean {
193:   if (!repoRoot) return false;
194:   const repoRootNormalized = repoRoot.replace(/\//gu, '\\').toLowerCase().replace(/\\+$/u, '');
195:   const tokens = tokenizeSegment(command);
196:   for (const token of tokens) {
197:     if (/^[a-zA-Z]:\\/u.test(token)) {
198:       const tokenNormalized = token.replace(/\//gu, '\\').toLowerCase();
199:       if (!tokenNormalized.startsWith(repoRootNormalized)) {
200:         // But allow drive-letter patterns inside regex/string quotes
201:         // by checking if the token was the actual command path or a search pattern.
202:         const isLikelyPattern = /[|*?[\]{}()]/u.test(token) || /\\\\/u.test(token);
203:         if (!isLikelyPattern) {
204:           return true;
205:         }
206:       }
207:     }
208:   }
209:   return false;
210: }
211: 
212: export function evaluateCommandSafety(command: string, repoRoot = ''): SafetyResult {
213:   const trimmed = String(command || '').trim();
214:   if (!trimmed) {
215:     return { safe: false, reason: 'empty command' };
216:   }
217: 
218:   if (referencesPathOutsideRepo(trimmed, repoRoot)) {
219:     return { safe: false, reason: 'command must stay within the caller repository scope' };
220:   }
221: 
222:   if (hasBlockedOperator(trimmed)) {
223:     return { safe: false, reason: 'shell chaining/redirection is not allowed' };
224:   }
225: 
226:   if (hasFileRedirection(trimmed)) {
227:     return { safe: false, reason: 'file redirection is not allowed' };
228:   }
229: 
230:   if (WRITE_OR_NETWORK_COMMAND_PATTERN.test(trimmed)) {
231:     return { safe: false, reason: 'destructive, file-writing, or network command is not allowed' };
232:   }
233: 
234:   const segments = splitTopLevelPipes(trimmed);
235:   const producerToken = getFirstCommandToken(segments[0] || '');
236:   if (producerToken !== PRODUCER_COMMAND) {
237:     return { safe: false, reason: `command '${producerToken || '<empty>'}' is not in the allow-list` };
238:   }
239: 
240:   for (const segment of segments.slice(1)) {
241:     const pipeToken = getFirstCommandToken(segment);
242:     if (!READ_ONLY_PIPE_COMMANDS.has(pipeToken)) {
243:       return { safe: false, reason: `command '${pipeToken || '<empty>'}' is not in the allow-list` };
244:     }
245:     if (/\bforeach-object\b/iu.test(segment) && FOREACH_WRITE_COMMAND_PATTERN.test(segment)) {
246:       return { safe: false, reason: 'ForEach-Object must be read-only' };
247:     }
248:   }
249: 
250:   return { safe: true, reason: null };
251: }
