83: // The one list of commands that write, delete, rename, or reach the network. It is applied to
84: // script-block bodies only; command positions are already governed by the allow-lists below.
85: const WRITE_OR_NETWORK_COMMAND_PATTERN = /\b(rm|del|mv|cp|move-item|copy-item|remove-item|rename-item|set-content|add-content|out-file|export-[a-z0-9_-]+|tee-object|curl|wget|invoke-webrequest|invoke-restmethod|start-process)\b/iu;
