87: type QuoteBlanking = { single: boolean; double: boolean };
88: 
89: /**
90:  * Replaces the interior of selected quoted spans with spaces, preserving length and quote
91:  * characters, so a scan sees only the shell syntax that can actually execute. Single-quoted spans
92:  * are literal in PowerShell; double-quoted spans still expand `$(...)` and honour the backtick
93:  * escape, but redirection and chaining operators inside them are inert text.
94:  */
95: function blankQuotedSpans(command: string, blanking: QuoteBlanking): string {
96:   let result = '';
97:   let inSingle = false;
98:   let inDouble = false;
99:   for (let index = 0; index < command.length; index += 1) {
100:     const char = command[index];
101:     if (char === "'" && !inDouble) {
102:       inSingle = !inSingle;
103:       result += char;
104:       continue;
105:     }
106:     if (char === '"' && !inSingle) {
107:       inDouble = !inDouble;
108:       result += char;
109:       continue;
110:     }
111:     const shouldBlank = (inSingle && blanking.single) || (inDouble && blanking.double);
112:     result += shouldBlank ? ' ' : char;
113:   }
114:   return result;
115: }
116: 
117: function hasBlockedOperator(operatorScan: string): boolean {
118:   for (let index = 0; index < operatorScan.length; index += 1) {
119:     const char = operatorScan[index];
120:     if (char === ';') {
121:       return true;
122:     }
123:     if (char === '&' && operatorScan[index + 1] === '&') {
124:       return true;
125:     }
126:     if (char === '|' && operatorScan[index + 1] === '|') {
127:       return true;
128:     }
129:   }
130:   return false;
131: }
132: 
133: function hasFileRedirection(operatorScan: string): boolean {
134:   // Strip safe stderr-to-stdout merges (2>&1) before checking for real file redirects
135:   return /[<>]/u.test(operatorScan.replace(/\s*2>&1\s*/gu, ' '));
136: }
