146:   for (let index = 0; index < expansionScan.length; index += 1) {
147:     if (expansionScan[index] === '{') {
148:       openIndexes.push(index);
149:       continue;
150:     }
151:     if (expansionScan[index] === '}') {
152:       const start = openIndexes.pop();
153:       if (start !== undefined) {
154:         bodies.push(expansionScan.slice(start + 1, index));
155:       }
156:     }
157:   }
158:   return bodies;
159: }
